let lockBoard,firstCard,secondCard,hasFlippedCard=!1,matches=0,attempts=0;const CARDS=document.querySelectorAll(".memory-card"),TIMER=document.getElementById("timer"),MATCHED=document.getElementById("matched"),ATTEMPTS=document.getElementById("attempts");let timerMinutes=0,timerSeconds=0;const MINUTES=document.getElementById("minutes"),SECONDS=document.getElementById("seconds");function flipCard(){if(!lockBoard&&this!==firstCard){if(this.classList.add("flip"),!hasFlippedCard)return hasFlippedCard=!0,void(firstCard=this);secondCard=this,checkForMatch()}}function checkForMatch(){firstCard.dataset.team===secondCard.dataset.team?disableCards():unflipCards(),attempts++,ATTEMPTS.textContent=attempts}function disableCards(){firstCard.removeEventListener("click",flipCard),secondCard.removeEventListener("click",flipCard),matches++,MATCHED.textContent=matches,resetBoard()}function unflipCards(){lockBoard=!0,setTimeout((()=>{firstCard.classList.remove("flip"),secondCard.classList.remove("flip"),resetBoard()}),1e3)}function resetBoard(){hasFlippedCard=!1,lockBoard=!1,firstCard=null,secondCard=null}ATTEMPTS.innerText=attempts,MATCHED.innerText=matches,CARDS.forEach((e=>{let t=Math.floor(64*Math.random());e.style.order=t})),CARDS.forEach((e=>e.addEventListener("click",flipCard)));let gameTimer=function(){timerSeconds++,timerSeconds>=60&&(timerSeconds=0,timerMinutes++),MINUTES.textContent=timerMinutes.toString().padStart(2,"0"),SECONDS.textContent=timerSeconds.toString().padStart(2,"0")};function gameCompleted(){clearInterval(gameTimer),startConfetti()}setInterval(gameTimer,1e3),32==matches&&gameCompleted();